/**
 * Org hierarchy CRUD actions.
 * @module     local_airpay_org/org_actions
 * @copyright  2026 Airpay Payment Services
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */
define("local_airpay_org/org_actions", [
    "core_form/modalform",
    "core/str",
    "core/notification",
    "core/ajax"
], function(ModalForm, Str, Notification, Ajax) {
    "use strict";

    var openOrgForm = function(orgid, parentid, returnFocus) {
        var titleKey = (orgid === 0) ? "addorg" : "editorg";
        Str.get_string(titleKey, "local_airpay_org").then(function(title) {
            var modalForm = new ModalForm({
                formClass: "local_airpay_org\\form\\edit_org",
                args: {orgid: orgid, parentid: parentid},
                modalConfig: {title: title, large: true},
                returnFocus: returnFocus
            });
            modalForm.addEventListener(modalForm.events.FORM_SUBMITTED, function(event) {
                var message = (event.detail && event.detail.message) || "Saved.";
                Notification.addNotification({message: message, type: "success"});
                window.location.reload();
            });
            modalForm.show();
            return null;
        }).catch(Notification.exception);
    };

    var confirmToggle = function(orgid, name, isVisible, returnFocus) {
        var titleKey = isVisible ? "hideorg" : "showorg";
        var msgKey = isVisible ? "confirmhide" : "confirmshow";
        Promise.all([
            Str.get_string(titleKey, "local_airpay_org"),
            Str.get_string(msgKey, "local_airpay_org", name),
            Str.get_string("orgvisibilitychanged", "local_airpay_org")
        ]).then(function(strings) {
            Notification.confirm(strings[0], strings[1], strings[0], null, function() {
                Ajax.call([{methodname: "local_airpay_org_toggle_visibility",
                            args: {orgid: orgid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[2], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
            });
            if (returnFocus) setTimeout(function() { returnFocus.focus(); }, 100);
            return null;
        }).catch(Notification.exception);
    };

    var confirmDelete = function(orgid, name, returnFocus) {
        Promise.all([
            Str.get_string("deleteorg", "local_airpay_org"),
            Str.get_string("confirmdelete", "local_airpay_org", name),
            Str.get_string("delete", "core"),
            Str.get_string("orgdeleted", "local_airpay_org")
        ]).then(function(strings) {
            Notification.deleteCancelPromise(strings[0], strings[1], strings[2], returnFocus).then(function() {
                Ajax.call([{methodname: "local_airpay_org_delete_org",
                            args: {orgid: orgid}}])[0]
                    .then(function() {
                        Notification.addNotification({message: strings[3], type: "success"});
                        window.location.reload();
                        return null;
                    }).catch(Notification.exception);
                return true;
            }, function() { return null; });
            return null;
        }).catch(Notification.exception);
    };

    var handleClick = function(event) {
        var trigger = event.target.closest("[data-action]");
        if (!trigger) return;
        var action = trigger.dataset.action;
        var orgid = parseInt(trigger.dataset.orgid || "0", 10);
        var parentid = parseInt(trigger.dataset.parentid || "0", 10);
        var name = trigger.dataset.name || "this organisation";
        var isVisible = trigger.dataset.visible === "1";
        switch (action) {
            case "create-org":       event.preventDefault(); openOrgForm(0, 0, trigger); break;
            case "add-child-org":    event.preventDefault(); openOrgForm(0, parentid, trigger); break;
            case "edit-org":         event.preventDefault(); openOrgForm(orgid, 0, trigger); break;
            case "toggle-org":       event.preventDefault(); confirmToggle(orgid, name, isVisible, trigger); break;
            case "delete-org":       event.preventDefault(); confirmDelete(orgid, name, trigger); break;
        }
    };

    return {
        init: function() {
            var root = document.querySelector('[data-region="airpay-org"]') || document.body;
            if (root.dataset.airpayOrgInit === "1") return;
            root.dataset.airpayOrgInit = "1";
            root.addEventListener("click", handleClick);
        }
    };
});
